    const needle = foldCase(view.query.trim());
    const all = plugin.store.modules().filter((module2) => !needle || foldCase(String(module2.title ?? "")).includes(needle)).sort((a, b) => compareStrings(String(a.title ?? ""), String(b.title ?? "")));
