function renderOrderedCollection(view, detail, collection, title3) {
  const entries2 = collection.entries;
  const wrap = section(
    detail,
    `${title3} (${entries2.length})`,
    "The order and grouping shown here come directly from the canonical collection."
  );
  if (!entries2.length) {
    empty(
      wrap,
      "Empty collection",
      "No entries are currently registered."
    );
    return;
  }
  let previousGroup = null;
  entries2.forEach(
    (entry, index) => {
      if (entry.group && entry.group !== previousGroup) {
        wrap.createDiv({
          cls: "los-list-group",
          text: entry.group
        });
        previousGroup = entry.group;
      }
      const source = readLibraryRecord(
        view.plugin.store.get(
          entry.sourceId
        )
      );
      const row3 = wrap.createDiv({
        cls: "los-pack-entry"
      });
      row3.createSpan({
        cls: "los-pack-order",
        text: String(index + 1)
      });
      const copy = row3.createDiv({
        cls: "los-route-row-copy"
      });
      const open = copy.createEl(
        "button",
        {
          cls: "los-shelf-entry-title is-clickable",
          attr: {
            type: "button"
          },
          text: source?.title ?? entry.sourceId
        }
      );
      open.addEventListener(
        "click",
        () => {
          if (!source) {
            return;
          }
          view.plugin.nav.openSourceDetail(
            source.id,
            view.groupId
          );
        }
      );
      if (entry.why) {
        copy.createDiv({
          cls: "los-shelf-why",
          text: entry.why
        });
      }
      const facts = [
        source?.sourceType,
        source?.year,
        source?.materialExists || source?.materialPath ? "local" : null,
        source?.url ? "online" : null
      ].filter(Boolean).join(" \xB7 ");
      if (facts) {
        copy.createDiv({
          cls: "los-route-meta",
          text: facts
        });
      }
    }
  );
}
function renderLegacyList(view, root) {
  const back = button(
    root,
    "\u2039 Library",
    () => view.plugin.nav.back(),
    "quiet"
  );
  back.addClass("los-route-back");
  const title3 = `${view.recordType.charAt(0).toUpperCase()}${view.recordType.slice(1)} records`;
  pageHeader(
    root,
    "Compatibility view",
    title3,
    view.domain ? `Domain: ${view.domain}` : "Legacy record families remain reachable until their migration gate closes."
  );
  const input = root.createEl(
    "input",
    {
      cls: "los-search los-route-search",
      attr: {
        type: "search",
        placeholder: `Search ${view.recordType} records\u2026`,
        "aria-label": `Search ${view.recordType}`
      }
    }
  );
  input.value = view.query;
  input.addEventListener(
    "input",
    async () => {
      view.query = input.value;
      await view.plugin.router.remember({
        name: "legacy-library-list",
        recordType: view.recordType,
        query: view.query,
        domain: view.domain
      });
      view.render();
    }
  );
  let rows2 = readLibraryRecords(
    view.plugin.store.search(
      view.query,
      [view.recordType]
    )
  );
  if (view.domain) {
    rows2 = rows2.filter(
      (record7) => record7.domain === view.domain
    );
  }
  rows2.sort(
    (left, right) => compareStrings(
      left.title,
      right.title
    )
  );
  if (!rows2.length) {
    empty(
      root,
      view.query ? "No matching records" : "No records",
      view.query ? "Try a shorter title, alias or ID." : `No ${view.recordType} records are projected.`
    );
    return;
  }
  const list3 = root.createDiv({
    cls: "los-route-list"
  });
  for (const record7 of rows2) {
    const row3 = list3.createEl(
      "button",
      {
        cls: "los-route-row is-clickable",
        attr: {
          type: "button",
          "data-record-id": record7.id
        }
      }
    );
    const copy = row3.createDiv({
      cls: "los-route-row-copy"
    });
    copy.createEl(
      "strong",
      {
        text: record7.title
      }
    );
    copy.createDiv({
      cls: "los-route-meta",
      text: [
        record7.role,
        record7.domain,
        record7.state
      ].filter(Boolean).join(" \xB7 ")
    });
    row3.createSpan({
      cls: "los-route-open",
      text: record7.path ? "Open file \u2192" : "Open \u2192"
    });
    row3.addEventListener(
      "click",
      () => {
        view.selectedElementId = record7.id;
        if (record7.path) {
          view.plugin.openAuthoredPath(
            record7.path
          );
          return;
        }
        view.plugin.nav.openRecord(
          record7.record
        );
      }
    );
  }
}

// src/features/library/home.ts
function renderHome(view, root) {
  if (view.collection === "sources") {
    view.renderSourceBrowser(root);
    return;
  }
  pageHeader(
    root,
    "Library",
    "Choose a thematic group",
    view.collection === "topic-packs" ? "Topic Packs are narrow, purpose-built and manually ordered collections." : "Open a domain to browse its learning sources."
  );
  view.renderCollectionSwitch(root);
  const groups = view.plugin.store.thematicGroups().map(readThematicGroup2).filter(
    (group3) => group3 !== null
  );
  if (!groups.length) {
    empty(
      root,
      "No thematic groups",
      "Rebuild the projection after defining thematic-group metadata."
    );
    return;
  }
  const grid = root.createDiv({
    cls: "los-group-grid los-library-group-grid"
  });
  for (const group3 of groups) {
    const count5 = view.collection === "topic-packs" ? view.plugin.store.topicPacksForGroup(group3.id).length : view.plugin.store.sourcesForGroup(group3.id).length;
    const card = grid.createEl(
      "button",
      {
        cls: "los-group-card is-clickable",
        attr: {
          type: "button",
          "aria-label": `Open ${group3.title}`
        }
      }
    );
    const head = card.createDiv({
      cls: "los-group-card-header"
    });
    head.createEl(
      "h2",
      {
        text: group3.title
      }
    );
    const countLabel = view.collection === "topic-packs" ? `pack${count5 === 1 ? "" : "s"}` : `source${count5 === 1 ? "" : "s"}`;
    head.createSpan({
      cls: "los-group-count",
      text: `${count5} ${countLabel}`
    });
    if (group3.description) {
      card.createEl(
        "p",
        {
          text: group3.description
        }
      );
    }
    card.createSpan({
      cls: "los-route-open",
      text: "Open \u2192"
    });
    card.addEventListener(
      "click",
      () => {
        view.selectedElementId = group3.id;
        view.plugin.nav.openLibraryGroup(
          view.collection,
          group3.id
        );
      }
    );
  }
}
function renderCollectionSwitch(view, root) {
  const switcher = root.createDiv({
    cls: "los-collection-switch",
    attr: {
      role: "group",
      "aria-label": "Library collection"
    }
  });
  enableButtonGroupKeyboardNavigation(switcher);
  button(
    switcher,
    "Folders",
    () => view.plugin.nav.openLibraryFolder([]),
    "quiet"
  );
  for (const [
    id,
    label2
  ] of LIBRARY_COLLECTIONS2) {
    const control = button(
      switcher,
      label2,
      () => view.plugin.nav.openLibraryHome(id),
      view.collection === id ? "cta" : "quiet"
    );
    control.setAttrs({
      "aria-pressed": String(
        view.collection === id
      )
    });
  }
}
function renderGroup2(view, root) {
  if (view.collection === "sources") {
    view.renderSourceBrowser(root);
    return;
  }
  const group3 = readThematicGroup2(
    view.groupId ? view.plugin.store.get(
      view.groupId
    ) : null
  );
  const back = button(
    root,
    "\u2039 Library",
    () => view.plugin.nav.back(),
    "quiet"
  );
  back.addClass("los-route-back");
  if (!group3) {
    empty(
      root,
      "Thematic group unavailable",
      "Return to Library and choose another group.",
      "Back",
      () => view.plugin.nav.back()
    );
    return;
  }
  pageHeader(
    root,
    "Topic Packs",
    group3.title,
    "Purpose-built collections in this thematic group."
  );
  const toolbar2 = root.createDiv({
    cls: "los-library-toolbar"
  });
  const input = toolbar2.createEl(
    "input",
    {
      cls: "los-search los-route-search",
      attr: {
        type: "search",
        placeholder: `Search ${group3.title} topic packs\u2026`,
        "aria-label": `Search ${group3.title} topic packs`
      }
    }
  );
  input.value = view.query;
  input.addEventListener(
    "input",
    async () => {
      view.query = input.value;
      await view.rememberGroup();
      view.render();
    }
  );
  const all = readLibraryRecords(
    view.plugin.store.topicPacksForGroup(group3.id)
  );
  const needle = foldCase(view.query.trim());
  const words2 = needle.split(/\s+/).filter(Boolean);
  const rows2 = all.filter((record7) => {
    if (!words2.length) {
      return true;
    }
    const hay = foldCase(
      [
        record7.id,
        record7.title,
        record7.purpose,
        record7.summary,
        ...record7.aliases,
        ...record7.authors,
        record7.organization
      ].filter(Boolean).join(" ")
    );
    return words2.every(
      (word) => hay.includes(word)
    );
  }).sort(
    (left, right) => compareStrings(left.title, right.title)
  );
  if (!all.length) {
    empty(
      root,
      "No Topic Packs in this group",
      "The group exists, but no purpose-built pack currently references it."
    );
    return;
  }
  if (!rows2.length) {
    empty(
      root,
      "No matching results",
      `Nothing in ${group3.title} matches the current search.`,
      "Clear search",
      async () => {
        view.query = "";
        await view.rememberGroup();
        view.render();
      }
    );
    return;
  }
  const list3 = root.createDiv({
    cls: "los-route-list los-library-route-list"
  });
  for (const record7 of rows2) {
    view.renderRecordRow(
      list3,
      record7,
      true
    );
  }
}

