async function selectTab(view, tab) {
  if (!view.moduleId) {
    return;
  }
  view.tab = tab;
  await view.plugin.router.remember({
    name: "module-detail",
    moduleId: view.moduleId,
    componentId: view.componentId,
    tab
  });
  await view.leaf.setViewState({
    type: VIEW_MODULE,
    active: true,
    state: {
      screen: "detail",
      moduleId: view.moduleId,
      componentId: view.componentId,
      tab
    }
  });
}
async function selectComponent(view, componentId) {
  if (!view.moduleId) {
    return;
  }
  view.componentId = componentId;
  const tab = view.tab ?? "units";
  await view.plugin.router.remember({
    name: "module-detail",
    moduleId: view.moduleId,
    componentId,
    tab
  });
  await view.leaf.setViewState({
    type: VIEW_MODULE,
    active: true,
    state: {
      screen: "detail",
      moduleId: view.moduleId,
      componentId,
      tab
    }
  });
}
function renderSources2(view, root, module2) {
  const sourceMap = view.plugin.store.sourceMap(
    module2.id
  );
  const entries2 = readSourceEntries(
    sourceMap ? sourceMap.sources : null
  );
  if (!entries2.length) {
    empty(
      root,
      "No routed module sources yet",
      "Sources remain globally registered."
    );
    return;
  }
  root.createEl("p", {
    cls: "los-muted",
    text: "Roles in this module \u2014 not global quality scores."
  });
  const groups = /* @__PURE__ */ new Map();
  for (const entry of entries2) {
    const current = groups.get(entry.role);
    if (current) {
      current.push(entry);
    } else {
      groups.set(
        entry.role,
        [entry]
      );
    }
  }
  for (const [role, roleEntries] of groups) {
    const group3 = root.createDiv({
      cls: "los-source-role"
    });
    group3.createDiv({
      cls: "los-group-title",
      text: role.replaceAll("-", " ")
    });
    for (const entry of roleEntries) {
      const row3 = group3.createDiv({
        cls: "los-row"
      });
      const source = entry.sourceId ? view.plugin.store.get(
        entry.sourceId
      ) : null;
      if (source) {
        chip(
          row3,
          source,
          (record7) => {
            const id = asString(
              record7.id
            );
            if (!id) {
              return;
            }
            return view.plugin.nav.openLibrary(id);
          }
        );
      }
      row3.createEl("p", {
        text: entry.why
      });
      if (entry.unitRouteCount) {
        row3.createDiv({
          cls: "los-micro",
          text: `${entry.unitRouteCount} routed unit(s)`
        });
      }
    }
  }
}

